package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamPolonnaruwaBank3 {
    private const val T = "පොළොන්නරු යුගයේ සිතුවම්, මූර්ති හා වාස්තු කලාව"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පොළොන්නරුවේ 'ලංකාතිලක' පිළිමගෙය ගොඩනඟන ලද්දේ කුමන රජතුමාගේ රාජ්‍ය කාලයේදීද?", "මහා පරාක්‍රමබාහු රජුගේ කාලයේදී", "නිශ්ශංකමල්ල රජුගේ කාලයේදී", "පළමුවන විජයබාහු රජුගේ කාලයේදී", "මහා විජයබාහු රජුගේ කාලයේදී", "පරාක්‍රමබාහු රජු විසින් ඉදිකරවන ලද ලංකාතිලකය දෙමහල් හුණුගල්-ගඩොල් ගෙඩිගේ සම්ප්‍රදායේ විශාලතම පිළිමගෙයකි."),
        q("ලංකාතිලක පිළිමගෙයි ඇතුළත වැඩ සිටින දැවැන්ත ගඩොල් හා බදාම හිටි බුදු පිළිමයේ ආසන්න උස කොපමණද?", "මීටර් 13ක් පමණ (අඩි 41ක් පමණ)", "මීටර් 3ක් පමණ (අඩි 10ක් පමණ)", "මීටර් 30ක් පමණ (අඩි 100ක් පමණ)", "මීටර් 5ක් පමණ (අඩි 16ක් පමණ)", "අවාසනාවකට හිස කොටස කැඩී ගොස් තිබුණද එහි දැවැන්ත ප්‍රමාණය පොළොන්නරු ගඩොල් මූර්ති ශිල්පය පෙන්වයි."),
        q("පොළොන්නරුවේ 'ථූපාරාම පිළිමගෙය' වර්තමානය දක්වාම නිරුපද්‍රිතව පවතින ප්‍රධාන වාස්තු අංගය කුමක්ද?", "සම්පූර්ණ ගඩොල් ආරුක්කුමය වහලය (Vaulted Roof)", "රන් ආලේපිත ලෝකඩ කොත් කැරැල්ල", "දැව කුළුණු සහිත මහනුවර පියස්ස", "කළුගල් වටදාගෙය සහ සඳකඩපහණ", "ගෙඩිගේ සම්ප්‍රදායට අයත් ථූපාරාමය අදටත් වහලය සම්පූර්ණයෙන් පවතින එකම පොළොන්නරු පිළිමගෙයයි."),
        q("පොළොන්නරුවේ දළදා මළුව තුළ පිහිටි 'හැටදාගෙය' ඉදි කරවන ලද්දේ කුමන රජතුමා විසින්ද?", "නිශ්ශංකමල්ල රජතුමා විසින්", "මහා පරාක්‍රමබාහු රජතුමා විසින්", "පළමුවන විජයබාහු රජතුමා විසින්", "දුටුගැමුණු රජතුමා විසින්", "පැය හැටකින් ඉදිකළ බව සැලකෙන හැටදාගෙය දන්ත ධාතූන් වහන්සේ තැන්පත් කිරීමට නිශ්ශංකමල්ල රජු තැනවීය."),
        q("දළදා මළුවේ පිහිටි 'අටදාගෙය' කරවන ලද්දේ පොළොන්නරු යුගයේ කුමන රජතුමා විසින්ද?", "පළමුවන විජයබාහු රජතුමා විසින්", "මහා පරාක්‍රමබාහු රජතුමා විසින්", "නිශ්ශංකමල්ල රජතුමා විසින්", "කීර්ති ශ්‍රී රාජසිංහ රජු විසින්", "චෝල පාලනයෙන් රට මුදාගත් පළමුවන විජයබාහු රජු විසින් දළදා වහන්සේ උදෙසා අටදාගෙය කරවන ලදී."),
        q("පොළොන්නරු වටදාගෙයි බාහිර කවයෙන් පසු ඇතුළු මළුවේ ඇති ශිලා කැටයම් පුවරුවල විශේෂ රටාව කුමක්ද?", "සිව්පෙති මල් කැටයම් සහිත ගල් වැට", "සත්ත්ව දඩයම් දැක්වෙන රේඛා සිතුවම්", "දහඅට සන්නි වෙස්මුහුණු පෙළ", "රාම රාවණා යුද පුවත් කැටයම්", "පොළොන්නරු වටදාගෙය පැරණි සාංචි ගල් වැට සිහිගන්වන ක්‍රමවත් ශිලා කැටයම්වලින් සමන්විතය."),
        q("පොළොන්නරුවේ 'සත්මහල් ප්‍රාසාදය' කුමන රටක වාස්තු ආකෘතියට සමීප සමානකමක් දක්වන බව විද්වතුන් පවසයිද?", "තායිලන්තයේ ලම්පුන් (හරිපුංජය) ස්තූපයට", "ඊජිප්තුවේ ගීසා මහා පිරමීඩයට", "ග්‍රීසියේ ඇතැන්ස් පාතනන් දෙවොලට", "ජපානයේ හොරියුජි ලී පැගෝඩාවට", "මහල් හතකින් යුත් ඝන ගඩොල් කුළුණු ආකෘතිය තායිලන්තයේ වට් කුකුට් වැනි දකුණු ආසියානු ස්තූප සිහිගන්වයි."),
        q("පොළොන්නරුවේ 'රන්කොත් වෙහෙර' ස්තූපය පැරණි අනුරාධපුර මහා ස්තූපවලින් වෙනස් වන ප්‍රධාන වාස්තු ලක්ෂණය කුමක්ද?", "දාගැබේ ගර්භය මත කුඩා ගඩොල් බුදු කුටි තිබීම", "දාගැබ සම්පූර්ණයෙන්ම කළුගලින් නිම කර තිබීම", "දාගැබ වටා වටදාගෙයක් ඉදිකර තිබීම", "කොත් කැරැල්ල වෙනුවට චත්‍රාවලියක් පැවතීම", "රන්කොත් වෙහෙර පාදමේ ඇති වාහල්කඩ හා ගර්භයේ අලංකාර බදාම නෙළීම් පොළොන්නරු ලක්ෂණ පෙන්වයි."),
        q("පොළොන්නරුවේ 'කිරි වෙහෙර' ඉදිකරන ලද්දේ කවුරුන් විසින්දැයි පිළිගැනේද?", "මහා පරාක්‍රමබාහු රජුගේ සුභද්‍රා දේවිය විසින්", "නිශ්ශංකමල්ල රජුගේ කල්‍යාණවතී බිසව විසින්", "පළමුවන විජයබාහු රජුගේ තිලෝකසුන්දරී විසින්", "දුටුගැමුණු රජුගේ විහාරමහා දේවිය විසින්", "පෙර රූපවාහිනී/පෙළපොත් අනුව 'සුභද්‍රා චේතිය' ලෙසද හැඳින්වුණු කිරි වෙහෙරේ මුල් හුණු බදාමය අදත් පවතී."),
        q("පොළොන්නරු යුගයේ සිතුවම් අතර 'පුල්ලිගොඩ ගල්ගෙය' පිහිටා ඇත්තේ කුමන ප්‍රදේශයේද?", "දිඹුලාගල ආසන්නයේ පොළොන්නරුවේ", "මහනුවර ගම්පොළ මාර්ගයේ", "අනුරාධපුර මිහින්තලේ කඳු පාමුල", "රත්නපුර සමනල අඩවියේ", "දිඹුලාගල මාරවීදිය හා පුල්ලිගොඩ සිතුවම් පොළොන්නරු යුගයේ චිත්‍ර ශෛලිය පිළිබඳ වැදගත් සාක්ෂි සපයයි."),
        q("පුල්ලිගොඩ ගල්ගෙයි සිතුවමෙහි නිරූපණය කර ඇති ප්‍රධාන විෂය වස්තුව කුමක්ද?", "නෙළුම් මල් පුදමින් වැඳ සිටින දිව්‍ය රූප පහක්", "සස ජාතකයේ හාවා ගිනි මැලයට පනින අවස්ථාව", "දුටුගැමුණු එළාර යුද පිටියේ අවස්ථාවක්", "මාර පරාජය හා සුජාතාවගේ කිරිපිඬු පූජාව", "සිවුරේ හා වස්ත්‍රයේ රේඛා ලාලිත්‍යය අතින් සීගිරි සම්ප්‍රදායට යම් නෑකමක් කියන දේව රූප පෙළ මෙහි දැක්වේ."),
        q("තිවංක පිළිමගෙයි ඇතුළත බිත්ති සිතුවම් අතර දක්නට ලැබෙන 'මෛත්‍රේය හෝ අසංඛවතී' වැනි රූප අයත් වන්නේ කුමන තේමා කාණ්ඩයටද?", "ජාතක කතා හා බුද්ධ චරිත පුවත්", "ඓතිහාසික රාජාවලිය හා යුද ජයග්‍රහණ", "දෛනික ගැමි ගොවිතැන් හා වෙළඳ කටයුතු", "හින්දු දේව පුරාණය හා කෛලාස කූටය", "තිවංක පිළිමගෙයි ප්‍රදක්ෂිණාපථයේ ජාතක කතාද අන්තරාලයේ හා ගර්භගෘහයේ බුදු සිරිතද ඇඳ ඇත."),
        q("තිවංක පිළිමගෙයි ගර්භගෘහයේ බුදු සිරිත නිරූපණය කිරීමේදී 'සංකස්සපුර දේවාවරෝහණය' ඇඳ ඇත්තේ කුමන ස්ථානයකද?", "උතුරු බිත්තියෙහි", "දකුණු බිත්තියෙහි", "බටහිර පිටත බිත්තියෙහි", "සිවිලිමේ මැද වෘත්තයෙහි", "තව්තිසා දෙව්ලොව අභිධර්මය දේශනා කර දෙව් බඹුන් පිරිවරා සංකස්සපුරයට වැඩීම උතුරු බිත්තියේ දැක්වේ."),
        q("තිවංක පිළිමගෙයි පිහිටි ජාතක කතා සිතුවම් අතර පහත සඳහන් කුමන ජාතක කතාව හඳුනාගෙන තිබේද?", "වෙස්සන්තර, සස හා විධුර ජාතක කතා", "උම්මග්ග, කට්ඨහාරි හා තේලපත්ත ජාතක", "මහාජනක, සුතසෝම හා චුල්ලධම්මපාල ජාතක", "අසාතමන්ත, නන්දිවිසාල හා කුස ජාතක", "වෙස්සන්තර, සස, මූගපක්ඛ (තේමිය), කාලිංගබෝධි හා විධුර ජාතකය තිවංක බිතුසිතුවම් අතර ප්‍රධාන වේ."),
        q("තිවංක පිළිමගෙයි ඇඳ ඇති සිතුවම්වල පැහැදිලිවම හඳුනාගත හැකි ප්‍රධාන බටහිර-ඉන්දියානු හා අජන්තා සමානකම කුමක්ද?", "සිරුරේ තානය හා මෘදු වක්‍ර රේඛා ලාලිත්‍යය", "තෙල් සායම් මිශ්‍ර ඉම්පැස්ටෝ පහරවල්", "මුහුණු සියල්ල පැතිකඩින් පමණක් ඇඳීම", "වස්තු සියල්ල ජ්‍යාමිතික කියුබ් හැඩයට බිඳීම", "පොළොන්නරු යුගයේ චිත්‍ර ශිල්පියා ත්‍රිමාණ බව හැඟවීමට රේඛාවෙන් හා තානයෙන් කළ උත්සාහය ප්‍රශස්තය."),
        q("තිවංක පිළිමගෙය අනුරාධපුර සීගිරි සිතුවම්වලින් වෙනස් වන ප්‍රධාන ශිල්පීය ලක්ෂණයක් කුමක්ද?", "ප්‍රකාශනශීලී රේඛා හා සමූහ රූප සංයුතිය", "රන්වන් හා තනි කොළ පාට පමණක් භාවිතය", "මානව රූප වෙනුවට සතුන් පමණක් ඇඳීම", "කඩදාසි මත ජල සායමින් නිර්මාණය කිරීම", "සීගිරියේ තනි/යුගල රූප වෙනුවට තිවංකයේ විශාල කතා පුවත් හා සංකීර්ණ සමූහ රූප ගොඩනගා ඇත."),
        q("ගල් විහාරයේ 'හිටි පිළිමය' (උස මීටර් 7ක් පමණ) බුදු පිළිමයක්ම බව තහවුරු කිරීමට පුරාවිද්‍යාඥයන් ඉදිරිපත් කරන ප්‍රධාන සාධකය කුමක්ද?", "හිසෙහි උෂ්ණීෂය, දක්ෂිණාවර්ත කෙස් හා ඌර්ණ රෝමය", "හිස මත රාජකීය ජටා මකුටයක් පැළඳ සිටීම", "දකුණු අතෙහි පුස්කොළ පොතක් දරා සිටීම", "පාද යට නාග පෙණ හතක් නෙළා තිබීම", "බුදුරජාණන් වහන්සේගේ දෙතිස් මහා පුරුෂ ලක්ෂණ මෙහි පැහැදිලිව නෙළා ඇති බැවින් එය පරදුක්ඛදුක්ඛිත බුදු පිළිමයකි."),
        q("ගල් විහාරයේ 'විශාල හිඳි බුදු පිළිමයේ' පසුබිම් මකර තොරණෙහි හරස් පොළු හෙවත් කුළුණු අතර කැටයම් කර ඇත්තේ මොනවාද?", "සිංහ රූප සහ විමාන රූප", "ඇත් රූප සහ ගව රූප", "නාග රූප සහ හංස රූප", "දේවතා රූප සහ කින්නර රූප", "උත්තරාරාමයේ විශාල හිඳි පිළිමය පිටුපස සිංහයන් හා මකර මුඛ සහිත දර්ශනීය තොරණක් ගලේම කොටා ඇත."),
        q("ගල් විහාරයේ 'විජ්ජාධර ගුහාව' තුළ වැඩ සිටින හිඳි බුදු පිළිමය දෙපස චාමර සලමින් සිටින රූප දෙකෙන් දැක්වෙන්නේ කවුරුන්ද?", "බ්‍රහ්ම සහ විෂ්ණු දෙවිවරුන්", "සැරියුත් සහ මුගලන් හිමිවරුන්", "ශිව සහ ගණ දෙවිවරුන්", "පරාක්‍රමබාහු සහ විජයබාහු රජවරුන්", "ගුහාව ඇතුළත හිඳි බුදු පිළිමය දෙපස ඉහළින් දේව රූප සහ චාමර ගත් රූප නෙළා තිබේ."),
        q("ගල් විහාරයේ 'විජ්ජාධර ගුහාව' පිටත බිත්තියේ දක්නට ලැබෙන පුරාණ බිතුසිතුවම්වල ඇඳ ඇති විෂය කුමක්ද?", "බුදුන් වැඳ පුදන වෘද්ධ තාපස හා දේව රූප", "දුටුගැමුණු එළාර රාජකීය සංග්‍රාමය", "අලි ඇතුන් සහිත පෙරහැර දර්ශනයක්", "ලියවැල් හා භේරුණ්ඩ පක්ෂි රටාවක්", "කළුගල් ගුහාවේ සිවිලිම හා බිත්ති මත හුණු බදාම ගා ඇඳි සිතුවම් කොටස් තවමත් ඉතිරිව පවතී."),
        q("පොළොන්නරුවේ 'ශිව නටරාජ' ලෝකඩ ප්‍රතිමාවේ පසුබිම වටා ඇති ගිනිදැල් වළල්ලෙන් (Prabhamandala) සංකේතවත් කරන්නේ කුමක්ද?", "විශ්වීය ශක්තිය හා කාල චක්‍රය", "ලෝකයේ සතර මහා ගංගා පද්ධතිය", "ශිව දෙවියන්ගේ රාජ්‍ය ඔටුන්න", "සංසාරයේ සත්ව පේළි හතර", "විශ්වයේ නිර්මාණය, පැවැත්ම හා විනාශය යන ශිව දෙවියන්ගේ පංච කෘත්‍යය නටරාජ ප්‍රතිමාවෙන් පෙන්වයි."),
        q("පොළොන්නරුවෙන් හමු වූ 'ශිව නටරාජ' ප්‍රතිමාවේ ඉහළ දකුණු අතෙහි දරා සිටින සංගීත භාණ්ඩය කුමක්ද?", "ඩමරු හෙවත් උඩැක්කි බෙරය", "වීණාව හෙවත් තන්තිරි භාණ්ඩය", "ශංඛය හෙවත් හක්ගෙඩිය", "බටනළාව හෙවත් වංශ නළාව", "ඉහළ දකුණු අතේ උඩැක්කිය මැවීමේ ශබ්දයද ඉහළ වම් අතේ ගිනිදැල් විනාශයද නිරූපණය කරයි."),
        q("පොළොන්නරුවේ 'ශිව දේවාල අංක 5' ආශ්‍රිත කැණීම්වලින් හමු වූ 'කරෙයික්කාල් අම්මයියාර්' ලෝකඩ ප්‍රතිමාවේ විශේෂත්වය කුමක්ද?", "අස්ථි මතු වූ කෘශ වෘද්ධ කාන්තා රුවකි", "සිංහයෙකු මත නගින රණකාමී තරුණියකි", "වීණාවක් වයන සරස්වතී දේවියකි", "පද්මාසන මත හිඳින ලක්ෂ්මී දේවියකි", "මහලු වියේ අස්ථි පෑදුණු ශිව භක්තික කිවිඳිය අතිශය යථාර්ථවාදීව හා හැඟීම්බරව ලෝකඩයෙන් වාත්තු කර ඇත."),
        q("පොළොන්නරුවෙන් හමු වූ 'සුන්දරමූර්ති ස්වාමි' ලෝකඩ ප්‍රතිමාව අයත් වන්නේ කුමන හින්දු භක්තික කණ්ඩායමටද?", "ශෛව නායන්මාර් සාන්තුවරයන්ට", "වෛෂ්ණව ආල්වාර් සාන්තුවරයන්ට", "මහායාන බෝධිසත්ව මණ්ඩලයට", "ජෛන තීර්ථංකර පරම්පරාවට", "චෝල ආභාසය සහිත ශිව දේවාලවලින් හමු වූ නායන්මාර් සාන්තුවරයන්ගේ ප්‍රතිමා ලංකාවේ හින්දු කලාවේ ඉහළම නිදසුන් වේ."),
        q("පොළොන්නරු යුගයේ ලෝකඩ ප්‍රතිමා නිපදවීමට යොදාගත් සාම්ප්‍රදායික වාත්තු ශිල්පීය ක්‍රමය හඳුන්වන්නේ කුමන නමින්ද?", "මධූච්ඡිෂ්ට විධානය (Lost-Wax Method)", "ගල් වැලි පුළුස්සන සෙරමික් ක්‍රමය", "ලෝහ තහඩු කටු ගසන රිපූසේ ක්‍රමය", "ප්ලාස්ටර් අච්චු සීතල වාත්තු ක්‍රමය", "මී ඉටියෙන් රුව සාදා මැටි ආවරණ දමා ඉටි උණු කර හිස් කුහරයට ලෝකඩ වත්කිරීම මෙහි ක්‍රමයයි."),
        q("පොළොන්නරුවේ පොත්ගුල් වෙහෙර අසල ඇති 'පරාක්‍රමබාහු ප්‍රතිමාවේ' මුහුණෙන් නිරූපණය වන විශේෂිත පුද්ගල ලක්ෂණ මොනවාද?", "දිගු රැවුල, උස් ජටාව හා සංයමී බැල්ම", "පළල් සිනහව හා නාග පෙණ ඔටුන්න", "කෙටි හිසකෙස් හා තුන්වන නළලේ ඇස", "වසා ගත් දෙනෙත් හා මුඩු හිස", "වයසින් මුහුකුරා ගිය ගාම්භීර පෙනුම හා අතේ ඇති පුස්කොළ පොත මෙම මූර්තියට සුවිශේෂී බරක් දෙයි."),
        q("පොත්ගුල් වෙහෙර ප්‍රතිමාව රජෙකු නොව 'අගස්ත්‍ය හෝ කපිල සෘෂිවරයෙකු' බවට ඇතැම් විද්වතුන් තර්ක කිරීමට හේතුව කුමක්ද?", "සෘෂි ජටාව, රැවුල, ලොකු බඳ හා පුස්කොළය", "පාද අසල සිංහ රූපයක් නොතිබීම", "පිළිමය කළුගලින් නිමවා තිබීම", "පිළිමය පොත්ගුල් වෙහෙරට උතුරින් තිබීම", "රාජාභරණ කිසිවක් නොමැතිව සරල උඩුකය නිරුවත්ව සිටීම මෙම විද්වත් මතභේදයට ප්‍රධාන හේතුවයි."),
        q("පොළොන්නරුවේ 'නිශ්ශංකලතා මණ්ඩපයේ' කළුගල් කුළුණු හැඩගන්වා ඇත්තේ කුමන ස්වාභාවික වස්තුවක ආකාරයෙන්ද?", "නැමී ගිය නෙළුම් මල් දණ්ඩක හැඩයෙන්", "ගල් පර්වතයක රළු බිඳුණු හැඩයෙන්", "කෙළින් නැගුණු පොල් ගස් කඳක හැඩයෙන්", "අටපට්ටම් ජ්‍යාමිතික හැඩයෙන්", "මල් අත්තක් සේ වක්‍ර වී මුදුනේ පිපුණු නෙළුම් මල් පොහොට්ටුවකින් අවසන් වන කුළුණු ශිලා කලාවේ විශිෂ්ට නිර්මාණයකි."),
        q("පොළොන්නරුවේ 'කුමාර පොකුණ' ආසන්නයේ ඇති කළුගල් ජල පීල්ල නිමවා ඇත්තේ කුමන සත්ව හිසක හැඩයෙන්ද?", "මකර හෝ කිඹුල් මුඛයක හැඩයෙන්", "සිංහ හෝ කොටි මුඛයක හැඩයෙන්", "හංස හෝ මොනර හොටක හැඩයෙන්", "ගජසිංහ හෝ අශ්ව හිසක හැඩයෙන්", "පරාක්‍රමබාහු රජුගේ උද්‍යාන මාලිගා සංකීර්ණයට අයත් කුමාර පොකුණ ශිලාමය ජල උද්‍යාන කලාවේ අග්‍ර ඵලයකි."),
        q("පොළොන්නරුවේ 'නෙළුම් පොකුණ' (Lotus Bath) ගොඩනඟා ඇත්තේ මුදුනේ සිට පතුල දක්වා කුමන හැඩයකට අනුවද?", "පිපුණු නෙළුම් මල් පෙති අටක තට්ටු ලෙස", "හතරැස් කොටු තට්ටු තුනක ආකාරයට", "සමපාද ත්‍රිකෝණාකාර පිරමීඩ ලෙස", "දඟර ගැසුණු සර්පිලාකාර මාර්ගයක් ලෙස", "නෙළුම් පෙති පහළට කුඩා වෙමින් යන සේ කළුගල් පුවරු කපා සකසා ඇති ආකාරය ඉතා අලංකාරය."),
        q("පොළොන්නරුවේ 'පරාක්‍රමබාහු රාජ සභා මණ්ඩපයේ' කුළුණු මත කැටයම් කර ඇති කලාත්මක මෝස්තරය කුමක්ද?", "සිංහ රූප, හංස පෙළ හා වාමන රූප", "බටහිර ඇකැන්තස් පත්‍ර හා සුරදූත රූප", "මහනුවර බිනරමල හා භේරුණ්ඩ රූප", "චීන මකර හා උණ බට රටා", "රාජ සභා මණ්ඩපයේ පාදම වටා ඇත්, සිංහ හා වාමන රූප තීරු පිළිවෙළින් පහළ සිට ඉහළට කැටයම් කර ඇත."),
        q("පොළොන්නරුවේ 'වෙජයන්ත ප්‍රාසාදය' හෙවත් මහා පරාක්‍රමබාහු රජුගේ මාලිගය පිළිබඳ වාස්තු විද්‍යාත්මක විශේෂත්වය කුමක්ද?", "මහල් හතකින් යුත් ඝන ගඩොල් හා දැව මැදුරකි", "සම්පූර්ණයෙන්ම කිරිගරුඬ ගලින් නිමවන ලදී", "තනි කළුගල් ගුහාවක් තුළ හාරා තනන ලදී", "පැරණි ලෝකඩ පත්‍රවලින් සෙවිලි කරන ලදී", "පළල් ගඩොල් බිත්ති මත දැව බාල්ක රඳවා මහල් කිහිපයක් ඉහළට ඉදිකළ බව සිදුරු සාධකවලින් පෙනේ."),
        q("පොළොන්නරුවේ 'දීප උයනේ' පිහිටි නිශ්ශංකමල්ල රාජ සභා මණ්ඩපයේ තිබූ සුප්‍රකට ශිලා සිංහාසනය දැනට කොහි තැන්පත් කර තිබේද?", "කොළඹ ජාතික කෞතුකාගාරයේ", "මහනුවර ශ්‍රී දළදා මාලිගාවේ", "ගාල්ල ලන්දේසි කොටුවේ කෞතුකාගාරයේ", "යාපනය පුරාවිද්‍යා කෞතුකාගාරයේ", "සිංහයාගේ ශරීරය මත කොටා ඇති ලිපි හා බලසම්පන්න මූර්ති ශෛලිය නිසා නිශ්ශංකමල්ල සිංහාසනය සුවිශේෂී වේ."),
        q("පොළොන්නරු යුගයේ 'මුරගල්' කලාව තුළ අනුරාධපුර මුරගල්වලට වඩා පෙනෙන විලාසිතාමය හා කලාත්මක වෙනස කුමක්ද?", "අධික සැරසිලි, ආභරණ හා තරබාරු රූප", "ඉතා සරල නිරුවත් ශෛලිගත රේඛා බව", "නාග රාජයන් වෙනුවට සිංහ රූප යෙදීම", "මුරගල් සම්පූර්ණයෙන්ම දැවයෙන් නිමවීම", "වටදාගෙයි මුරගල්වල සියුම් කැටයම් වැඩි වී ඇතත් අනුරාධපුර රත්නප්‍රාසාදයේ සරල ගාම්භීර ලාලිත්‍යය අඩු වී ඇත."),
        q("පොළොන්නරු යුගයේ 'වටදාගෙය' ආශ්‍රිත සඳකඩපහණ අනුරාධපුර සඳකඩපහණින් වෙනස් වන ප්‍රධාන කරුණු දෙක මොනවාද?", "ගවයා ඉවත් වීම හා සතුන් වෙන වෙනම තීරු ගත වීම", "නෙළුම් මල වෙනුවට සූර්ය චක්‍රය පැවතීම", "ලියවැල ඉවත් වී ජ්‍යාමිතික කොටු රටා පැවතීම", "සඳකඩපහණ හතරැස් පුවරුවක් බවට පත්වීම", "හින්දු ආගමික ගෞරවය නිසා ගවයා ඉවත් කර ඇත් හා අශ්ව රූප වෙනම වෘත්තාකාර තීරුවලට වෙන් කර ඇත."),
        q("පොළොන්නරුවේ 'ශිව දේවාල අංක 1' කුමන දකුණු ඉන්දීය රාජවංශ වාස්තු සම්ප්‍රදායේ ආභාසය වැඩිපුර පෙන්වයිද?", "පාණ්ඩ්‍ය වාස්තු සම්ප්‍රදායේ", "මෞර්ය වාස්තු සම්ප්‍රදායේ", "ගාන්ධාර වාස්තු සම්ප්‍රදායේ", "මෝගල් වාස්තු සම්ප්‍රදායේ", "ශිව දේවාල අංක 2 චෝල සම්ප්‍රදාය පෙන්වන අතර ශිව දේවාල අංක 1 පසුකාලීන පාණ්ඩ්‍ය ගෘහ නිර්මාණ ලක්ෂණ ගනී."),
        q("පොළොන්නරු යුගයේ 'ගඩොල් හා බදාම' (Brick and Stucco) බාහිර බිත්ති කැටයම් විශේෂයෙන්ම දැකිය හැකි දේව විමාන හා රූප මොනවාද?", "විමාන මන්දිර තුළ වැඩ සිටින දේව රූප", "කඩු පලිහ ගත් යුද භටයන්ගේ පෙළපාලි", "මුහුදු යාත්‍රා හා වරාය වෙළඳ දර්ශන", "වන සතුන් දඩයම් කරන ගැමි රූප", "තිවංක, ලංකාතිලක හා ථූපාරාම පිටත බිත්තිවල දේව රූප සහිත කුඩා විමාන ගෙවල් බදාමයෙන් අලංකාර කර ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාර හිටි පිළිමයේ' චීවරයේ දැකිය හැකි සිවුරු රැලි (Drapery Folds) කැටයම් කර ඇති ක්‍රමය කුමක්ද?", "සමාන්තර වක්‍ර රේඛා ද්විත්ව ඉරි රිද්මයකට", "කිසිදු රැල්ලක් නැතිව සම්පූර්ණ සිනිඳුවට", "ත්‍රිකෝණාකාර ජ්‍යාමිතික කොටු රටාවකට", "තද ගැඹුරු අවුල් සහගත කැඩුණු ඉරිවලට", "සිරුරේ සිට පහළට රිද්මයානුකූලව ගලා යන සමාන්තර ද්විත්ව රේඛා පොළොන්නරු යුගයේ චීවර ලක්ෂණයකි."),
        q("පොළොන්නරු යුගයේ 'කොරවක්ගල්' (Balustrades) අනුරාධපුර යුගයේ කොරවක්ගල්වලට වඩා කෙබඳු හැඩයක් ගනීද?", "වඩාත් අලංකාර හා සංකීර්ණ මකර ගජසිංහ රූප", "කිසිදු කැටයමක් නොමැති පැතලි ගල් පුවරු", "සරල හංස රූප පමණක් කෙටූ කෙටි ගල්", "දැවයෙන් තැනූ ලියවැල් වැටවල්", "පොළොන්නරු කොරවක්ගල්වල මකර මුඛයෙන් නික්මෙන ගජසිංහ හෝ ව්‍යාඝ්‍ර රූප ඉතා විසිතුරු ලෙස නෙළා තිබේ."),
        q("පොළොන්නරුවේ 'ආලාහන පිරිවෙන' සංකීර්ණයට අයත් ප්‍රධාන පූජනීය ගොඩනැගිලි මොනවාද?", "රන්කොත් වෙහෙර, ලංකාතිලකය හා බද්ධසීමා ප්‍රාසාදය", "වටදාගෙය, හැටදාගෙය හා අටදාගෙය", "ගල් විහාරය, පොත්ගුල් වෙහෙර හා තිවංකය", "ශිව දේවාල අංක 2 හා නිශ්ශංකලතා මණ්ඩපය", "පරාක්‍රමබාහු රජු විසින් කරවන ලද ආලාහන පිරිවෙන ප්‍රධාන ආරාමික අධ්‍යාපන හා කලා සංකීර්ණයකි."),
        q("පොළොන්නරුවේ 'බද්ධසීමා ප්‍රාසාදය' හඳුනාගනු ලබන්නේ කුමන විහාර අංගයක් ලෙසද?", "භික්ෂූන් වහන්සේලාගේ උපෝසථාගාරය හෙවත් පොහොයගෙය", "රජුගේ ගිම්හාන ජල ක්‍රීඩා මාලිගය", "හින්දු භක්තිකයන්ගේ ප්‍රධාන කෝවිල", "දන්ත ධාතූන් වහන්සේ වැඩ සිටි මන්දිරය", "විශාල උස් වේදිකාවක් මත සීමා ගල් සතර දිසාවේ පිහිටුවා උපෝසථ කර්ම සඳහා මෙය ඉදිකරන ලදී."),
        q("පොළොන්නරුවේ 'පබළු වෙහෙර' නමැති ස්තූපයේ ගෘහ නිර්මාණ ලක්ෂණ අනුව එය විශේෂ වන්නේ ඇයි?", "පේසා වළලු මත කුඩා ගඩොල් පිළිමගෙවල් තිබීම", "දාගැබේ ගර්භය මුළුමනින්ම පබළු ගල්වලින් සෑදීම", "දාගැබ වටා විශාල දිය අගලක් පිහිටීම", "මහනුවර යුගයේ පියස්සක් දාගැබ උඩ තිබීම", "පළමුවන විජයබාහු හෝ පරාක්‍රමබාහු රජුගේ බිසවක විසින් කරවූ බව සැලකෙන මෙහි බදාම කැටයම් විශිෂ්ටය."),
        q("පොළොන්නරු යුගයේ 'මැණික් වෙහෙර' ස්තූපයේ බිත්ති වටා කැටයම් කර ඇති සුවිශේෂී සත්ව රූප මාලාව කුමක්ද?", "ටෙරාකොටා හෙවත් පිළිස්සූ මැටි සිංහ රූප", "කළුගලින් නෙළූ මකර හා නාග රූප", "ලෝකඩින් වාත්තු කළ හංස රූප පෙළ", "කිරිගරුඬ ගලින් නෙළූ අශ්ව රූප පෙළ", "මැණික් වෙහෙර ස්තූප වේදිකාව අලංකාර කිරීමට පිළිස්සූ මැටි සිංහ රූප පේළියක් යොදා තිබීම සුවිශේෂීය."),
        q("පොළොන්නරු යුගයේ 'වටදාගෙයි' පිළිම හතර මැද පිහිටි කුඩා ස්තූපය ඉදිරිපස ඇති ප්‍රධාන පූජනීය වස්තුව කුමක්ද?", "සිව් දිසාවට මුහුණලා ඇති හිඳි බුදු පිළිම සතර", "පරාක්‍රමබාහු රජුගේ සිංහාසන සතර", "ශිව නටරාජ ලෝකඩ ප්‍රතිමා සතර", "පුන්කලස් සහිත ගල් කුළුණු අට", "සතර බුදුවරුන් හෝ සිව් දිසාව සංකේතවත් කරමින් කළුගලින් නෙළූ ධ්‍යාන මුද්‍රා බුදු පිළිම හතරක් තබා ඇත."),
        q("පොළොන්නරුවේ 'ගල් විහාර සැතපෙන පිළිමයේ' දකුණු පාදයට වඩා වම් පාදය මදක් පසුපසට ඇද තැබීමෙන් මූර්ති ශිල්පියා පෙන්නුම් කළේ කුමක්ද?", "පිරිනිවන් පෑ නිසල ස්වභාවික විවේක ඉරියව්ව", "උදෑසන නින්දෙන් අවදි වීමට සූදානම් වන බව", "පිළිමයේ පාදය කැඩී ගිය නිසා සිදු කළ වෙනසක්", "වේගයෙන් ඇවිද යන ගමන් ඉරියව්වක්", "දෙපා පිටුපසට මදක් ඇල කර තැබීමෙන් සජීවී විවේකී බව හා පිරිනිවන් මංචකයේ ගාම්භීරත්වය මතු කරයි."),
        q("ගල් විහාර සැතපෙන පිළිමයේ අත්ලෙහි හා පතුල්වල කැටයම් කර ඇති පූජනීය සංකේතය කුමක්ද?", "නෙළුම් මල (පද්ම ලකුණ)", "ත්‍රිශූලය හා ඩමරු බෙරය", "දුන්න හා රන් ඊතලය", "සඳ හා තාරකා ලකුණ", "බුදුන් වහන්සේගේ මහා පුරුෂ ලක්ෂණ සිහිගන්වන පද්ම සලකුණ අත්ලේ හා දෙපතුල්වල සියුම්ව නෙළා ඇත."),
        q("පොළොන්නරු යුගයේ 'ශිව දේවාල අංක 2' කළුගල් බිත්ති බැඳීමේදී ශිල්පීන් භාවිත කළ විශේෂ ඉදිකිරීම් තාක්ෂණය කුමක්ද?", "බදාම නොමැතිව ගල් එකිනෙකට කැපී සවි කිරීම", "යකඩ ඇණ හා ඊයම් වත්කර ගල් ඇලවීම", "හුණු හා වැලි ඝන බදාමයකින් ගල් බැඳීම", "දැව පටි ගල් අතර තබා තද කිරීම", "අන්තර්-අගුළු ගැසූ කළුගල් කුට්ටි (Dry Masonry) භාවිතය නිසා මෙය සියවස් ගණනාවක් නොසැලී පවතී."),
        q("පොළොන්නරුවේ 'තිවංක පිළිමගෙයි' මැද වැඩ සිටින ප්‍රධාන ගඩොල් බුදු පිළිමය 'තිවංක' ලෙස හඳුන්වන්නේ ඇයි?", "ශරීරය දණහිස, ඉණ හා ගෙල යන තුන් තැනකින් නැමී ඇති බැවින්", "පිළිමගෙය මහල් තුනකින් යුක්තව තැනූ බැවින්", "බිත්ති තුනක පමණක් සිතුවම් ඇඳ ඇති බැවින්", "පිළිමය රාජවංශ තුනකින් ඉදි කළ බැවින්", "ශරීරයේ ත්‍රිභංග නැම්ම නිසා දැවැන්ත ප්‍රතිමාවට අතිශය ලාලිත්‍යමය හා සජීවී පෙනුමක් ලැබී ඇත."),
        q("පොළොන්නරු යුගයේ 'මහායාන හා තාන්ත්‍රික' ආභාසය පෙන්වන හුණුගල් හෝ ලෝකඩ ප්‍රතිමා ලංකාවෙන් හමු වී ඇත්තේ කුමන ආකාරයෙන්ද?", "බහු-බාහු සහිත තාරා හා අවලෝකිතේශ්වර රූප", "තනි රේඛීය ගුහා චිත්‍ර ලෙස පමණක්", "කාසි මත කෙටූ අකුරු ලෙස පමණක්", "ලී වෙස්මුහුණු කැටයම් ලෙස පමණක්", "ථේරවාද බුදු දහම ප්‍රමුඛ වුවද විවිධ ආගමික සහජීවනය පොළොන්නරු ලෝකඩ ප්‍රතිමාවලින් පැහැදිලි වේ."),
        q("පොළොන්නරු යුගයේ 'දිඹුලාගල මාරවීදිය' ගල්ලෙනෙහි පිහිටි සිතුවම්වල විශේෂත්වය කුමක්ද?", "සස ජාතකය හා දිව්‍ය මාලිගා දර්ශන ඇඳීම", "බටහිර යුද නැව් සිතුවම් කර තිබීම", "පැරණි වැදි දඩයම් අළු සිතුවම් පැවතීම", "නූතන තෙල් සායමින් රූප ඇඳ තිබීම", "තිවංක සිතුවම් සමඟ කාලීන වන මාරවීදිය සිතුවම් පොළොන්නරු චිත්‍ර කලාවේ වැදගත් පුරුකකි."),
        q("පොළොන්නරු යුගයේ 'සිංහල හා චෝල' කලා සම්ප්‍රදායන් දෙකම හමු වන නගරයක් ලෙස පොළොන්නරුව විශේෂ වන්නේ ඇයි?", "චෝල ආක්‍රමණ හා පසුකාලීන රාජ්‍ය විවාහ නිසා", "බ්‍රිතාන්‍ය හා ලන්දේසි පාලන සමය නිසා", "චීන හා ජපන් වෙළඳ ගිවිසුම් නිසා", "ග්‍රීක රෝම තානාපති සබඳතා නිසා", "10-11 සියවස්වල චෝල පාලනය තුළ ඉදි වූ ශිව දේවාල හා ඉන්පසු සිංහල රජවරුන්ගේ බෞද්ධ කලා අංග මෙහි මුසු විය."),
        q("පොළොන්නරුවේ 'රාජ මාලිගා සංකීර්ණයේ' බිත්ති හා සිවිලිම් වර්ණවත් කිරීමට අතීතයේ භාවිත කළ බවට සාධක ඇත්තේ කුමක්ද?", "ඔප දැමූ සුදු හුණු බදාම හා සිතුවම් සලකුණු", "සම්පූර්ණ වීදුරු කැබලි මොසැයික් ස්තර", "රබර් හා ප්ලාස්ටික් වර්ණ පුවරු", "තෙල් සායම් ගෑ කැන්වස් රෙදි ආවරණ", "ගඩොල් බිත්ති පිටතින් හා ඇතුළතින් සුදු හුණු බදාමයෙන් වසා ඔප දමා තිබූ බව පුරාවිද්‍යා කැණීම්වලින් හෙළි වේ."),
        q("පොළොන්නරු යුගයේ 'කාලිංග මාඝගේ' ආක්‍රමණයෙන් පසු කලා නිර්මාණවලට අත් වූ ප්‍රධාන ඉරණම කුමක්ද?", "රාජරට ශිෂ්ටාචාරය බිඳ වැටී කලාව නිරිතට යාම", "පොළොන්නරුවේ නව පිරමීඩ ඉදි වීම ආරම්භ වීම", "තෙල් සායම් චිත්‍ර කලාව පොළොන්නරුවේ ඇරඹීම", "සියලුම කළුගල් පිළිම රත්තරනින් ආවරණය කිරීම", "13 වන සියවසේ ආක්‍රමණ නිසා වාරි හා විහාර කලාව දඹදෙණිය, යාපහුව, කුරුණෑගල හා ගම්පොළට සංක්‍රමණය විය."),
        q("පොළොන්නරුවේ 'ගල් විහාර හිටි පිළිමයේ' උස මීටර් 7ක් පමණ වන අතර එය නෙළා ඇති පර්වත පසුබිම කෙබඳුද?", "පර්වතය ගැඹුරට හාරා අර්ධ උන්නතව නිමවා ඇත", "සම්පූර්ණයෙන් ගලෙන් වෙන් කර එළිමහනේ තබා ඇත", "ගඩොලින් බිත්ති බැඳ බදාමයෙන් අඹා ඇත", "කළුගල් කුට්ටි කිහිපයක් එක මත එක තබා ඇත", "මුල් කාලයේ මෙම ප්‍රතිමා වටා ගඩොල් බිත්ති හා වහල සහිත පිළිමගෙවල් තිබූ බවට අත්තිවාරම් සාධක ඇත."),
        q("පොළොන්නරුවේ 'ගණ දෙවි' (Ganesha) ලෝකඩ ප්‍රතිමා අතර හමු වී ඇති සුවිශේෂී කලා ලක්ෂණය කුමක්ද?", "ඇත් හිස හා මිනිස් සිරුරේ සංතුලිත මූර්ති බව", "සිංහ හිස හා මත්ස්‍ය වලිගය එක්ව තිබීම", "පියාපත් දෙකක් හා කඩුවක් දරා සිටීම", "හිස් පහක් හා පාද අටක් සහිත වීම", "ශිව දේවාලවලින් හමු වූ ගණේෂ, පාර්වතී හා කාර්තිකේය ප්‍රතිමා හින්දු ආගමික ප්‍රතිමා ශාස්ත්‍රයට අනුව නිමවා ඇත."),
        q("පොළොන්නරු යුගයේ 'ශිව දේවාල අංක 2' මුදුනේ ඇති ශිඛරය හෙවත් ශිලාමය ගෝලාකාර කොටසේ විශේෂත්වය කුමක්ද?", "චෝල ද්‍රවිඩ අෂ්ටාස්‍ර කූට ශිඛර ශෛලියයි", "අනුරාධපුර බුබ්බුලාකාර ස්තූප හැඩයයි", "මහනුවර පෙති උළු දෙපල වහල ශෛලියයි", "රෝම ගෝලාකාර කොන්ක්‍රීට් ගෝල හැඩයයි", "පහළ සිට ඉහළට ක්‍රමයෙන් කුඩා වන විමාන තට්ටු සහිත දකුණු ඉන්දීය විමාන ගෘහ නිර්මාණය මෙහි පැහැදිලිය."),
        q("පොළොන්නරුවේ 'ගල්පොත' ශිලා ලේඛනය අසල දෙපසින් කැටයම් කර ඇති 'ගජලක්ෂ්මී' කැටයමෙන් දැක්වෙන්නේ කුමක්ද?", "ඇතුන් දෙදෙනෙකු ජලය ඉසින ලක්ෂ්මී දේවිය", "සිංහයන් දෙදෙනෙකු මැද සිටින දුටුගැමුණු රජු", "නෙළුම් මල් ගත් හංස පූට්ටු යුගලය", "වීණාව වයන සරස්වතී දේවිය හා පිරිවර", "කළුගල් පොතේ කෙළවර ඇති ඇතුන් හා ලක්ෂ්මී රුව සෞභාග්‍යයේ හා රාජ්‍ය ශ්‍රීයේ සංකේතයකි."),
        q("පොළොන්නරු යුගයේ බිතුසිතුවම්වල භාවිත කළ 'රතු-තැඹිලි' හා 'කහ' වැනි වර්ණ ලබා ගැනීමට ශිල්පියා යොදාගත් ස්වභාවික ඛනිජ මොනවාද?", "සාදිලිංගම්, ගුරුගල් හා හිරියල් ඛනිජ", "කෘත්‍රිම කැඩ්මියම් රතු හා ක්‍රෝම් කහ", "රසායනික ඇනලයින් ඩයි හා ඇක්‍රිලික්", "දියර ගල් අඟුරු තාර හා සිමෙන්ති කුඩු", "අනුරාධපුර සීගිරියේ මෙන්ම පොළොන්නරු යුගයේද ස්වභාවික ඛනිජ හා පස් වර්ණක සියුම්ව අඹරා භාවිත කර ඇත."),
        q("තිවංක පිළිමගෙයි ඇතුළත සිතුවම් 'සෙක්කෝ' (Fresco Secco) ක්‍රමයට වඩා 'බුවොන් ෆ්‍රෙස්කෝ' ක්‍රමයට ආසන්න වන්නේ කෙසේද?", "හුණු වැලි බදාමයේ තෙතමනය ඇති විට ඇඳීමෙන්", "වියළි ලී පුවරු මත ඉටි මිශ්‍ර කර ඇඳීමෙන්", "කඩදාසි මත ජල සායම් ගා බිත්තියේ ඇලවීමෙන්", "තෙල් මිශ්‍ර තීන්තයෙන් වියළි ගඩොලේ ඇඳීමෙන්", "තෙත් හුණු බදාමය සමඟ වර්ණක රසායනිකව බැඳීම නිසා පොළොන්නරු සිතුවම් සියවස් අටක් තිස්සේ නොනැසී පවතී."),
        q("පොළොන්නරුවේ 'රන්කොත් වෙහෙර' සහ 'මිරිසවැටිය' අතර ඇති ප්‍රධාන වාස්තු සමානකම කුමක්ද?", "සිව් දිසාවේ කැටයම් කළ වාහල්කඩ පිහිටීම", "මහල් හතකින් යුත් හතරැස් පිරමීඩ හැඩය", "වටාපතක හැඩයෙන් යුත් ලෝහ වහලය", "කළුගලින් පමණක් නිමවූ ගර්භ කොටස", "රුවන්වැලිසෑය ආදර්ශයට ගනිමින් මහා පරාක්‍රමබාහු හෝ නිශ්ශංකමල්ල රජු රන්කොත් වෙහෙර විශාලව ගොඩනැංවීය."),
        q("පොළොන්නරුවේ 'නිශ්ශංකමල්ල' රජුගේ කලා නිර්මාණ තුළ බොහෝ විට දැකිය හැකි පෞද්ගලික ලක්ෂණය කුමක්ද?", "තම නම හා ශිලා ලේඛන කැටයම්වල කෙටීම", "කිසිදු ශිලා ලේඛනයක් නොතබා සැඟවීම", "බුදු පිළිම වෙනුවට අශ්ව පිළිම පමණක් තැනීම", "දැව නිර්මාණ පමණක් කරවා ගල් අත්හැරීම", "නිශ්ශංකමල්ල රජු හැටදාගෙය, වටදාගෙය, ගල්පොත හා රංකොත් වෙහෙරේ තම කීර්තිය ශිලා ලේඛනගත කළේය."),
        q("අ.පො.ස. සාමාන්‍ය පෙළ චිත්‍ර කලා විෂය නිර්දේශයේ පොළොන්නරු යුගය හැදෑරීමෙන් සිසුන් අවබෝධ කර ගන්නා ප්‍රධාන සංස්කෘතික ලක්ෂණය කුමක්ද?", "දේශීය හා ඉන්දීය කලා ආභාසය සුසංයෝග වීම", "යුරෝපීය පුනරුද කලාවේ සෘජු පිටපත් කිරීම", "ප්‍රාග් ඓතිහාසික ගල් ආයුධ නිෂ්පාදන ක්‍රම", "නූතන වියුක්ත කලාවේ ජ්‍යාමිතික රීති", "සීගිරි ආභාසය, චෝල ලෝකඩ තාක්ෂණය හා පොළොන්නරු බෞද්ධ මූර්ති ශිල්පය අපූර්ව ලෙස එක් වූ යුගය මෙයයි.")
    )
}
